\title{A Polynomial Realization of the $\mu$-Corrected Sharp/Flat $\lambda$-Difference}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
For an elliptic curve $E/\QQ$ with good supersingular reduction at $2$ and a
squarefree twisting parameter $D \equiv 1 \pmod 4$, the difference between the
\emph{sharp} and \emph{flat} Iwasawa $\lambda$-invariants of the quadratic twist
$E^D$ is classically expressed, in the $\mu = 0$ case, as a finite sum of local
terms over the prime divisors of $D$. We record an extension of this formula
valid for arbitrary $\mu$: the sharp/flat difference acquires a correction
proportional to $\mu$, with an explicit weight built from $2$-adic depths of the
twisting primes. Our main contribution is a cross-domain bridge: we show that
this arithmetic invariant is realized, on the nose, as the genuine algebraic
Iwasawa invariants of an explicit integer polynomial, the characteristic
element. We define the polynomial $\mu$- and $\lambda$-invariants via content
valuation (Gauss's lemma) and trailing degree of the mod-$p$ reduction, prove
their additivity, and exhibit a polynomial whose $\mu$-invariant equals the
prescribed $\mu$ and whose $\lambda$-invariant equals the corrected sharp/flat
difference. As corollaries we obtain a polynomial-level inversion formula
recovering $\mu$, a non-vanishing theorem, strict monotonicity in $\mu$, and
additivity over coprime twisting parameters unifying two a priori different
additivity mechanisms.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Background and motivation}
Let $E/\QQ$ be an elliptic curve and $p$ a prime. Iwasawa theory attaches to $E$
over the cyclotomic $\ZZ_p$-extension a \emph{characteristic element}
$f \in \Lambda = \ZZ_p[[T]]$, whose two fundamental invariants are the
$\mu$-invariant $\mu_p(f)$ and the $\lambda$-invariant $\lambda_p(f)$. In the
good ordinary case these govern the growth of Selmer groups up the tower. In the
good supersingular case, the naive characteristic element fails to lie in
$\Lambda$, and one works instead with the Pollack--Sprung $\pm$ (equivalently
sharp/flat $\sharp/\flat$) theory, producing a pair $f^\sharp, f^\flat$ and a
pair of invariants $\lambda^\sharp, \lambda^\flat$.

For squarefree $D \equiv 1 \pmod 4$ the quadratic twist $E^D$ has its own
sharp/flat invariants, and in the base case $\mu = 0$ a formula in the tradition
of Matsuno expresses their difference as a sum of local contributions,
\[
  \lambda^\sharp - \lambda^\flat = \sum_{\ell \mid D} \localTerm(\ell),
\]
where each summand depends only on $\ell$ and the reduction data of $E$.

\subsection{The extension and the bridge}
We do two things. First (Section~\ref{sec:model}) we make precise the extension
to non-zero $\mu$: the difference picks up a term $\mu \sum_{\ell \mid D} 2^{n_\ell}$,
where $n_\ell = v_2((\ell^2-1)/8)$ is a $2$-adic depth, giving
\[
  \Lambda(D,\mu) = \sum_{\ell \mid D} \localTerm(\ell) + \mu \sum_{\ell \mid D} 2^{n_\ell}.
\]
Second (Sections~\ref{sec:poly}, \ref{sec:bridge}, \ref{sec:cor}) we establish a
bridge to commutative algebra: we define genuine polynomial Iwasawa invariants
on $\ZZ[X]$ and construct an explicit polynomial whose $\mu$-invariant is exactly
$\mu$ and whose $\lambda$-invariant is exactly $\Lambda(D,\mu)$. All results rest
only on Gauss's lemma, additivity of $p$-adic valuation, and additivity of
trailing degree over an integral domain.

\section{Polynomial Iwasawa invariants}\label{sec:poly}
Fix a prime $p$. For $f \in \ZZ[X]$ write $\cont(f)$ for its content (the
non-negative gcd of its coefficients) and $\pp(f)$ for its primitive part, so
$f = \cont(f)\cdot \pp(f)$ with $\pp(f)$ primitive.

\begin{definition}[reduction]
For a prime $p$, let $\bar f \in \FF_p[X]$ denote the reduction of $f$ mapping
each coefficient to $\ZZ/p\ZZ$.
\end{definition}

\begin{definition}[polynomial $\mu$-invariant]
$\mu_p(f) = v_p(\cont(f))$, the $p$-adic valuation of the content.
\end{definition}

\begin{definition}[polynomial $\lambda$-invariant]
$\lambda_p(f) = \ord_0(\overline{\pp(f)})$, the order of vanishing at $0$ of the
mod-$p$ reduction of the primitive part; equivalently the least index of a
non-zero coefficient of $\overline{\pp(f)}$.
\end{definition}

These faithfully model the invariants of a genuine characteristic element
$f = p^\mu u\, g$ (with $u$ a unit and $g$ distinguished) obtained from
Weierstrass preparation in $\Lambda$: the power of $p$ is the content, and the
distinguished polynomial's order of vanishing is the trailing degree of the
reduction.

\begin{lemma}[reduction of a primitive polynomial is non-zero]\label{lem:redne}
If $f \neq 0$ then $\overline{\pp(f)} \neq 0$.
\end{lemma}
\begin{proof}
If $\overline{\pp(f)} = 0$ then $p \mid \pp(f)_i$ for all $i$, so the constant
$p$ divides $\pp(f)$. As $\pp(f)$ is primitive, any common divisor of its
coefficients is a unit; but $p \geq 2$ is not a unit in $\ZZ$, a contradiction.
\end{proof}

\begin{theorem}[$\mu$ additive]\label{thm:muadd}
For nonzero $f,g \in \ZZ[X]$, $\mu_p(fg) = \mu_p(f) + \mu_p(g)$.
\end{theorem}
\begin{proof}
By Gauss's lemma $\cont(fg) = \cont(f)\cont(g)$; both are nonzero, and
$v_p$ is additive on products.
\end{proof}

\begin{theorem}[$\lambda$ additive]\label{thm:lamadd}
For nonzero $f,g \in \ZZ[X]$, $\lambda_p(fg) = \lambda_p(f) + \lambda_p(g)$.
\end{theorem}
\begin{proof}
The primitive part is multiplicative (Gauss), and reduction is a ring
homomorphism, so $\overline{\pp(fg)} = \overline{\pp(f)}\cdot\overline{\pp(g)}$.
By Lemma~\ref{lem:redne} both factors are nonzero in the integral domain
$\FF_p[X]$, where trailing degrees add under multiplication.
\end{proof}

\begin{corollary}[elementary invariants]\label{cor:elem}
$(1)$ $\mu_p(1)=\lambda_p(1)=0$.
$(2)$ $\mu_p(p^k)=k$ and $\lambda_p(p^k)=0$.
$(3)$ $\mu_p(X^n)=0$ and $\lambda_p(X^n)=n$.
\end{corollary}
\begin{proof}
$(1)$ $1$ has content $1$ and reduction $1$. $(2)$ $\cont(p^k)=p^k$ and primitive
part $1$. $(3)$ $X^n$ is monic hence primitive; its reduction $X^n$ has trailing
degree $n$.
\end{proof}

\begin{corollary}[powers and products]\label{cor:prod}
For nonzero polynomials, $\mu_p(g^n)=n\,\mu_p(g)$ and $\lambda_p(g^n)=n\,\lambda_p(g)$,
and for a finite family $(g_i)_{i\in S}$ of nonzero polynomials
$\mu_p(\prod_i g_i)=\sum_i \mu_p(g_i)$ and $\lambda_p(\prod_i g_i)=\sum_i \lambda_p(g_i)$.
\end{corollary}
\begin{proof}
Induct on $n$ and on $|S|$ using Theorems~\ref{thm:muadd}--\ref{thm:lamadd} and
that products of nonzero polynomials over a domain are nonzero.
\end{proof}

\section{The arithmetic model: extended Matsuno formula}\label{sec:model}
Fix reduction data encoded in $N_E \in \NN$ and $\ord : \NN \to \NN$.

\begin{definition}[$2$-adic depth]
For an odd prime $\ell$, $n_\ell = v_2((\ell^2-1)/8)$. Since $8 \mid \ell^2-1$
this is a well-defined non-negative integer.
\end{definition}

\begin{proposition}[depth law]\label{prop:depth}
For every odd prime $\ell$, $\;8\cdot 2^{n_\ell} = 2^{v_2(\ell-1)+v_2(\ell+1)}$.
\end{proposition}
\begin{proof}
$v_2(\ell^2-1) = v_2(\ell-1)+v_2(\ell+1)$ since $\ell^2-1=(\ell-1)(\ell+1)$;
dividing by $8=2^3$ gives $n_\ell = v_2(\ell^2-1)-3$, so
$8\cdot 2^{n_\ell} = 2^{3+n_\ell} = 2^{v_2(\ell^2-1)}$.
\end{proof}

\begin{definition}[local term]
\[
  \localTerm(\ell) =
  \begin{cases}
    2^{n_\ell}, & \ell \mid N_E,\\
    2^{n_\ell+1}, & \ell \nmid N_E \text{ and } 2 \mid \ord(\ell),\\
    0, & \text{otherwise.}
  \end{cases}
\]
\end{definition}

\begin{definition}
For squarefree $D$: the classical difference $\lamdiff(D)=\sum_{\ell\mid D}\localTerm(\ell)$,
the local $\mu$-weight $w(\ell)=2^{n_\ell}$, the total weight $W(D)=\sum_{\ell\mid D}2^{n_\ell}$,
and the extended Matsuno invariant
\[
  \Lambda(D,\mu) = \lamdiff(D) + \mu\,W(D) = \sum_{\ell\mid D}\localTerm(\ell) + \mu\sum_{\ell\mid D}2^{n_\ell}.
\]
\end{definition}

\begin{proposition}[properties of $\Lambda$]\label{prop:Lam}
$(1)$ $W(D)>0$ iff $D$ has a prime divisor.
$(2)$ $\Lambda(D,0)=\lamdiff(D)$.
$(3)$ If $\gcd(a,b)=1$ and $a,b\neq 0$ then $\Lambda(ab,\mu)=\Lambda(a,\mu)+\Lambda(b,\mu)$.
\end{proposition}
\begin{proof}
$(1)$ Each $2^{n_\ell}>0$, so the sum is positive iff the index set is nonempty.
$(2)$ Immediate. $(3)$ The prime factors of $ab$ are the disjoint union of those
of $a$ and $b$; split both sums over this union and regroup.
\end{proof}

\section{The bridge: the characteristic element}\label{sec:bridge}

\begin{definition}[local factor, $\mu$-factor, characteristic element]
$\lf(\ell) = X^{\localTerm(\ell)}$, $\quad \mf(D,\mu)=(p\,X^{W(D)})^\mu$,
\[
  \charElt(D,\mu) = \Big(\prod_{\ell\mid D}\lf(\ell)\Big)\cdot\mf(D,\mu)
  = \Big(\prod_{\ell\mid D} X^{\localTerm(\ell)}\Big)\cdot (p\,X^{W(D)})^\mu.
\]
\end{definition}
All factors are nonzero.

\begin{lemma}[invariants of the factors]\label{lem:fac}
$(1)$ $\mu_p(\lf(\ell))=0$ and $\lambda_p(\lf(\ell))=\localTerm(\ell)$.
$(2)$ $\mu_p(\mf(D,\mu))=\mu$ and $\lambda_p(\mf(D,\mu))=\mu\,W(D)$.
\end{lemma}
\begin{proof}
$(1)$ is Corollary~\ref{cor:elem}(3). For $(2)$, $p\,X^{W(D)}=C(p)\cdot X^{W(D)}$
has $\mu_p=1+0=1$ and $\lambda_p=0+W(D)=W(D)$ by additivity and
Corollary~\ref{cor:elem}; raising to the $\mu$-th power and applying
Corollary~\ref{cor:prod} multiplies each by $\mu$.
\end{proof}

\begin{theorem}[$\mu$-realization]\label{thm:mureal}
For all $D,\mu$, $\;\mu_p(\charElt(D,\mu))=\mu$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:prod} and Lemma~\ref{lem:fac}(1) the product of local
factors contributes $0$; the $\mu$-factor contributes $\mu$ by
Lemma~\ref{lem:fac}(2).
\end{proof}

\begin{theorem}[the bridge: $\lambda$-realization]\label{thm:lamreal}
For all $D,\mu$, $\;\lambda_p(\charElt(D,\mu))=\Lambda(D,\mu)$.
\end{theorem}
\begin{proof}
By $\lambda$-additivity (Corollary~\ref{cor:prod}),
$\lambda_p(\charElt(D,\mu)) = \sum_{\ell\mid D}\lambda_p(\lf(\ell)) + \lambda_p(\mf(D,\mu))$.
By Lemma~\ref{lem:fac} this is $\lamdiff(D) + \mu\,W(D) = \Lambda(D,\mu)$.
\end{proof}

\section{Corollaries of the bridge}\label{sec:cor}

\begin{corollary}[base case]
$\lambda_p(\charElt(D,0))=\lamdiff(D)$.
\end{corollary}

\begin{corollary}[$\mu$-recovery / inversion]\label{cor:rec}
If $D$ has a prime divisor, then
\[
  \frac{\lambda_p(\charElt(D,\mu)) - \lamdiff(D)}{W(D)} = \mu = \mu_p(\charElt(D,\mu)).
\]
\end{corollary}
\begin{proof}
By Theorem~\ref{thm:lamreal} the numerator is $\mu\,W(D)$ and $W(D)>0$
(Proposition~\ref{prop:Lam}(1)); the final equality is Theorem~\ref{thm:mureal}.
\end{proof}

\begin{corollary}[non-vanishing correction]
If $D$ has a prime divisor and $\mu>0$, then $\lamdiff(D) < \lambda_p(\charElt(D,\mu))$.
\end{corollary}
\begin{proof}
The right side is $\lamdiff(D)+\mu\,W(D)$ with $\mu\,W(D)>0$.
\end{proof}

\begin{corollary}[strict monotonicity in $\mu$]
If $D$ has a prime divisor, $\mu\mapsto\lambda_p(\charElt(D,\mu))$ is strictly
increasing; distinct $\mu$ yield distinct $\lambda$-invariants.
\end{corollary}
\begin{proof}
The map is $\mu\mapsto\lamdiff(D)+\mu\,W(D)$, affine with positive slope $W(D)$.
\end{proof}

\begin{corollary}[coprime additivity of the realized $\lambda$]\label{cor:coprime}
If $\gcd(a,b)=1$ and $a,b\neq 0$, then
$\lambda_p(\charElt(ab,\mu))=\lambda_p(\charElt(a,\mu))+\lambda_p(\charElt(b,\mu))$.
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:lamreal} and Proposition~\ref{prop:Lam}(3).
\end{proof}

Corollary~\ref{cor:coprime} exhibits, through the bridge, the
commutative-algebra additivity of the trailing degree (Theorem~\ref{thm:lamadd})
and the number-theoretic additivity of a sum over disjoint prime divisors as one
and the same statement.

\section{Worked examples}
Fix $p=2$, $\ord\equiv 1$, $N_E=1$, so every local term vanishes and
$\lamdiff(D)=0$, isolating the pure $\mu$-correction.

\begin{example}
$D=3$, $\mu=1$: $n_3=0$, $W(3)=1$, $\Lambda(3,1)=1$, and $\charElt(3,1)=2X$ has
content $2$ ($\mu_2=1$) and primitive part $X$ ($\lambda_2=1$).
\end{example}
\begin{example}
$D=15$, $\mu=2$: $n_3=n_5=0$, $W(15)=2$, $\Lambda(15,2)=4$, and
$\charElt(15,2)=(2X^2)^2=4X^4$: $\mu_2=2$, $\lambda_2=4$.
\end{example}
\begin{example}
$D=7$, $\mu=1$: $n_7=1$, $W(7)=2$, $\Lambda(7,1)=2$, $\charElt(7,1)=2X^2$:
$\mu_2=1$, $\lambda_2=2$. Coprime check: $\Lambda(3,1)+\Lambda(5,1)=2=\Lambda(15,1)$.
\end{example}

\section{Discussion}
The bridge reframes a delicate arithmetic computation as a robust algebraic one:
the sharp/flat $\lambda$-difference is at once a sum over twisting primes weighted
by $2$-adic depths and the order of vanishing of an explicit polynomial's mod-$p$
reduction. The $\mu$-invariant, invisible in the classical formula, is recorded
as content divisibility and is recoverable from the realized $\lambda$-data
(Corollary~\ref{cor:rec}); the non-vanishing and monotonicity statements show the
correction genuinely and monotonically moves $\lambda$.

\section{Future directions}
\begin{enumerate}
\item \textbf{Beyond powers of $X$.} Replace local factors by distinguished
polynomials with prescribed trailing behaviour to capture the position of
sign changes in the $\pm$-theory; the additivity engine already supports this.
\item \textbf{A power-series model.} Port $\mu_p,\lambda_p$ to $\ZZ_p[[T]]$ via
Weierstrass preparation, replacing content/primitive-part by
$p^\mu\cdot(\text{unit})\cdot(\text{distinguished})$.
\item \textbf{Sharp/flat pair as a single object.} Combine $f^\sharp,f^\flat$ and
prove $\lambda^\sharp-\lambda^\flat$ is $\mu$-proportional on the realized
polynomials.
\item \textbf{Functoriality.} Package $\charElt$ as a monoid homomorphism from
twist data into nonzero integer polynomials and show the invariants factor
through it.
\item \textbf{Effective depth law.} Extend $8\cdot2^{n_\ell}=2^{v_2(\ell-1)+v_2(\ell+1)}$
to a closed form for $W(D)$, enabling exact asymptotics.
\end{enumerate}

\section{Conclusion}
We extended the Matsuno-type sharp/flat $\lambda$-difference formula to
non-vanishing $\mu$ with an explicit linear correction $\mu\sum_{\ell\mid D}2^{n_\ell}$,
and realized the resulting invariant exactly as the polynomial Iwasawa invariants
of an explicit integer polynomial, deducing inversion, non-vanishing,
monotonicity, and coprime-additivity from elementary commutative algebra.

\end{document}

