"""Demo 2: Bridge verification with a genuine integer-polynomial engine.

Builds charElt(D, mu) as an honest element of Z[X], then computes its genuine
polynomial Iwasawa invariants (mu = v_p of content, lambda = trailing degree of
the mod-p reduction of the primitive part) and checks that they equal the
arithmetic model mu and lambdaDiffMu(D, mu).
"""
from __future__ import annotations
from math import gcd
from functools import reduce
from typing import Callable, Dict, List


def padic_val(p: int, n: int) -> int:
    if n == 0:
        return 0
    n, v = abs(n), 0
    while n % p == 0:
        n //= p
        v += 1
    return v


def prime_factors(n: int) -> List[int]:
    out, d, m = [], 2, n
    while d * d <= m:
        if m % d == 0:
            out.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def depth(ell: int) -> int:
    return padic_val(2, (ell * ell - 1) // 8)


def local_term(ell: int, NE: int, order: Callable[[int], int]) -> int:
    if NE % ell == 0:
        return 2 ** depth(ell)
    if order(ell) % 2 == 0:
        return 2 ** (depth(ell) + 1)
    return 0


def weight_sum(D: int) -> int:
    return sum(2 ** depth(ell) for ell in prime_factors(D))


def lambda_diff_mu(D: int, NE: int, mu: int, order: Callable[[int], int]) -> int:
    return sum(local_term(l, NE, order) for l in prime_factors(D)) + mu * weight_sum(D)


class IntPoly:
    def __init__(self, coeffs: Dict[int, int]) -> None:
        self.coeffs = {e: c for e, c in coeffs.items() if c != 0}

    def __mul__(self, o: "IntPoly") -> "IntPoly":
        out: Dict[int, int] = {}
        for e1, c1 in self.coeffs.items():
            for e2, c2 in o.coeffs.items():
                out[e1 + e2] = out.get(e1 + e2, 0) + c1 * c2
        return IntPoly(out)

    def __pow__(self, n: int) -> "IntPoly":
        r = IntPoly({0: 1})
        for _ in range(n):
            r = r * self
        return r

    def content(self) -> int:
        return 0 if not self.coeffs else reduce(gcd, (abs(c) for c in self.coeffs.values()))


def mu_inv(p: int, f: IntPoly) -> int:
    return padic_val(p, f.content())


def lambda_inv(p: int, f: IntPoly) -> int:
    c = f.content()
    reduced = {e: (coeff // c) % p for e, coeff in f.coeffs.items() if (coeff // c) % p}
    return min(reduced)


def char_elt(p: int, D: int, NE: int, mu: int, order: Callable[[int], int]) -> IntPoly:
    r = IntPoly({0: 1})
    for ell in prime_factors(D):
        r = r * IntPoly({local_term(ell, NE, order): 1})
    return r * (IntPoly({weight_sum(D): p}) ** mu)


if __name__ == "__main__":
    p, NE, order = 2, 1, (lambda _l: 1)
    for D, mu in [(3, 1), (5, 3), (7, 1), (15, 2), (105, 4), (231, 2)]:
        f = char_elt(p, D, NE, mu, order)
        assert mu_inv(p, f) == mu
        assert lambda_inv(p, f) == lambda_diff_mu(D, NE, mu, order)
